// Edit these two values after importing.
const ADMIN_CHAT_ID = 'YOUR_TELEGRAM_CHAT_ID';
const MODEL = 'gpt-4o-mini';
const MAX_CHARS = 2000; // caps LLM cost per message
const msg = $input.first().json.message || {};
const text = (msg.text || '').trim();
return [{ json: {
  admin_chat_id: ADMIN_CHAT_ID,
  model: MODEL,
  chat_id: msg.chat?.id,
  chat_type: msg.chat?.type || null,
  username: msg.from?.username || null,
  first_name: msg.from?.first_name || null,
  text: text.slice(0, MAX_CHARS),
  truncated: text.length > MAX_CHARS,
  message_id: msg.message_id,
  received_at: new Date((msg.date || Date.now() / 1000) * 1000).toISOString(),
} }];

// Drops anything we should not spend LLM tokens on. Returning [] ends the run.
const LIMIT = 5, WINDOW_MS = 10 * 60 * 1000; // 5 messages per chat per 10 min
const j = $input.first().json;
if (j.chat_type !== 'private' || !j.chat_id || !j.text) return [];
const store = $getWorkflowStaticData('global');
const now = Date.now();
store.rate = store.rate || {};
for (const [id, hits] of Object.entries(store.rate)) {
  const fresh = hits.filter((t) => now - t < WINDOW_MS);
  if (fresh.length) store.rate[id] = fresh; else delete store.rate[id];
}
const hits = store.rate[j.chat_id] || [];
if (hits.length >= LIMIT) return [];
store.rate[j.chat_id] = [...hits, now];
return [{ json: j }];

// Defensive parsing: never let a malformed LLM answer crash the flow.
const ctx = $('Config').first().json;
let data = {};
try {
  data = JSON.parse($input.first().json.choices[0].message.content);
} catch (e) {
  data = { intent: 'question', summary: 'Unparseable LLM output', reply: "Thanks! I'll get back to you shortly." };
}
// Whitelist model fields so a prompt-injected answer can never override
// trusted context such as chat_id or admin_chat_id.
const FIELDS = ['intent', 'name', 'company', 'email', 'need', 'budget', 'urgency', 'lead_score', 'summary', 'reply'];
data = Object.fromEntries(FIELDS.map((k) => [k, data && typeof data === 'object' ? data[k] ?? null : null]));
if (typeof data.reply !== 'string' || !data.reply.trim()) data.reply = "Thanks! I'll get back to you shortly.";
data.reply = data.reply.slice(0, 1000);
const allowed = ['lead', 'question', 'spam'];
if (!allowed.includes(data.intent)) data.intent = 'question';
const score = Number.parseInt(data.lead_score, 10);
data.lead_score = Number.isFinite(score) ? Math.max(0, Math.min(100, score)) : 0;
return [{ json: { ...data, ...ctx } }];

// Sanitise before writing to Sheets: stop formula injection (=HYPERLINK, =IMPORTXML...)
// and cap lengths, because these values come from strangers and an LLM.
const clean = (v, max = 500) => {
  if (v === null || v === undefined) return '';
  let s = String(v).replace(/[\u0000-\u0008\u000B\u000C\u000E-\u001F]/g, '').slice(0, max);
  if (/^[=+\-@\t\r]/.test(s)) s = "'" + s;
  return s;
};
const j = $input.first().json;
const email = /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(j.email || '') ? j.email : '';
const urgency = ['low', 'medium', 'high'].includes(j.urgency) ? j.urgency : 'medium';
return [{ json: {
  received_at: j.received_at,
  // Telegram usernames are [A-Za-z0-9_] only, so '@' + username is safe as-is.
  telegram_user: /^\w{4,32}$/.test(j.username || '') ? '@' + j.username : clean(j.first_name, 100),
  chat_id: String(j.chat_id),
  name: clean(j.name, 100), company: clean(j.company, 100), email: clean(email, 200),
  need: clean(j.need), budget: clean(j.budget, 100), urgency,
  lead_score: j.lead_score, summary: clean(j.summary),
  raw_message: clean(j.text, 2000), status: 'new',
} }];

